import { defineCollection, z } from "astro:content";
import { glob } from "astro/loaders";

// Online reading version of the "Israel is Attacking Wikipedia" report.
// Files are generated by scripts/wikipedia-report/convert.mjs; do not edit them by hand.
const wikipediaReport = defineCollection({
  loader: glob({ pattern: "*.md", base: "./src/content/wikipedia-report" }),
  schema: z.object({
    slug: z.string(),
    kind: z.enum(["front", "section", "appendix"]),
    label: z.string().optional(),
    title: z.string(),
    order: z.number().int(),
    toc: z.array(
      z.object({
        number: z.string().optional(),
        title: z.string(),
        depth: z.number().int().min(2).max(4),
        id: z.string(),
      })
    ),
  }),
});

// Chapters of the incubator project leader guide (/incubator/guide), taken
// word for word from the incubator's Google Doc: keep the Doc's wording and
// only change formatting. `order` sets reading order and the file name is the
// URL slug. The welcome tab lives in src/data/incubator-guide-welcome.md.
const incubatorGuide = defineCollection({
  loader: glob({ pattern: "*.md", base: "./src/content/incubator-guide" }),
  schema: z.object({
    title: z.string(),
    /** Meta description only: the chapter's opening sentence from the Doc. */
    description: z.string(),
    order: z.number().int(),
    /** The Doc's heading above this chapter, shown as its overline. */
    part: z.string().optional(),
  }),
});

export const collections = { wikipediaReport, incubatorGuide };
